// Designed silhouettes for Levels 21+.
//
// Every level name maps to one silhouette designed from simple geometric
// primitives, stored once at 64x64 (cropped to the design's own outline)
// with up to three colour regions per shape (e.g. petals / centre / stem).
// [ShapeArt.fit] scales a silhouette to any board size by area coverage.
//
// Encoding: rows separated by '|', each row a run-length list of
// <symbol><count> where '.' is empty and 'a'/'b'/'c' are regions 0/1/2.
import '../../models/puzzle_path.dart';

class ShapeArt {
  static const int source = 64;

  static bool has(String name) => _art.containsKey(name.toLowerCase());

  /// [name]'s silhouette scaled to fit a [box] x [box] square (proportions
  /// kept, centred), as cell -> colour region (0 primary, 1 secondary,
  /// 2 accent). Null when no art exists for [name].
  static Map<GridPoint, int>? fit(String name, int box) {
    final src = _decode(name);
    if (src == null || box <= 0) return null;

    // Tight bounds of the design.
    var x0 = source, y0 = source, x1 = -1, y1 = -1;
    for (int y = 0; y < source; y++) {
      for (int x = 0; x < source; x++) {
        if (src[y * source + x] >= 0) {
          if (x < x0) x0 = x;
          if (x > x1) x1 = x;
          if (y < y0) y0 = y;
          if (y > y1) y1 = y;
        }
      }
    }
    if (x1 < 0) return {};
    final w = x1 - x0 + 1, h = y1 - y0 + 1;
    final k = box / (w > h ? w : h); // target cells per source pixel
    final tw = (w * k).round().clamp(1, box);
    final th = (h * k).round().clamp(1, box);
    final ox = (box - tw) ~/ 2, oy = (box - th) ~/ 2;

    final out = <GridPoint, int>{};
    for (int j = 0; j < th; j++) {
      final sy0 = y0 + j / k, sy1 = y0 + (j + 1) / k;
      for (int i = 0; i < tw; i++) {
        final sx0 = x0 + i / k, sx1 = x0 + (i + 1) / k;
        final weight = [0.0, 0.0, 0.0];
        var area = 0.0;
        for (int py = sy0.floor(); py < sy1.ceil(); py++) {
          if (py < 0 || py >= source) continue;
          final oy_ = _overlap(py.toDouble(), sy0, sy1);
          for (int px = sx0.floor(); px < sx1.ceil(); px++) {
            if (px < 0 || px >= source) continue;
            final a = oy_ * _overlap(px.toDouble(), sx0, sx1);
            area += a;
            final r = src[py * source + px];
            if (r >= 0) weight[r] += a;
          }
        }
        final filled = weight[0] + weight[1] + weight[2];
        if (area > 0 && filled / area >= 0.45) {
          var best = 0;
          if (weight[1] > weight[best]) best = 1;
          if (weight[2] > weight[best]) best = 2;
          out[GridPoint(ox + i, oy + j)] = best;
        }
      }
    }
    return _bridge(out, box);
  }

  static double _overlap(double p, double a, double b) {
    final lo = p > a ? p : a;
    final hi = (p + 1) < b ? p + 1 : b;
    return hi > lo ? hi - lo : 0;
  }

  /// Gives every cell an edge neighbour: a cell touching the shape only at
  /// a corner gets one bridging cell (thin diagonal strokes stay one
  /// connected stroke), and fully isolated specks are dropped.
  static Map<GridPoint, int> _bridge(Map<GridPoint, int> cells, int box) {
    bool hasEdge(GridPoint c) =>
        cells.containsKey(GridPoint(c.x + 1, c.y)) ||
        cells.containsKey(GridPoint(c.x - 1, c.y)) ||
        cells.containsKey(GridPoint(c.x, c.y + 1)) ||
        cells.containsKey(GridPoint(c.x, c.y - 1));
    var changed = true;
    while (changed) {
      changed = false;
      final keys = cells.keys.toList()
        ..sort((a, b) => a.y != b.y ? a.y - b.y : a.x - b.x);
      for (final c in keys) {
        if (hasEdge(c)) continue;
        for (final d in const [[1, 1], [-1, 1], [1, -1], [-1, -1]]) {
          if (!cells.containsKey(GridPoint(c.x + d[0], c.y + d[1]))) continue;
          final bridge = GridPoint(c.x + d[0], c.y);
          if (bridge.x >= 0 && bridge.x < box) {
            cells[bridge] = cells[c]!;
            changed = true;
          }
          break;
        }
      }
    }
    cells.removeWhere((c, _) => !hasEdge(c));
    return cells;
  }

  static List<int>? _decode(String name) {
    final data = _art[name.toLowerCase()];
    if (data == null) return null;
    final out = List<int>.filled(source * source, -1);
    final rows = data.split('|');
    for (int y = 0; y < rows.length && y < source; y++) {
      final row = rows[y];
      var x = 0, i = 0;
      while (i < row.length) {
        final sym = row.codeUnitAt(i++);
        var n = 0;
        while (i < row.length) {
          final c = row.codeUnitAt(i);
          if (c < 0x30 || c > 0x39) break;
          n = n * 10 + (c - 0x30);
          i++;
        }
        final region = sym == 0x2E ? -1 : sym - 0x61;
        for (int k = 0; k < n && x < source; k++) {
          out[y * source + x++] = region;
        }
      }
    }
    return out;
  }

